#!/bin/bash
# Evaluate the held-out test slice without rerunning any method.
#
# Positional arguments mirror scripts/evaluate.sh:
#   ./scripts/evaluate_test.sh <data_path> <outputs_dir> <scores_path>
#
# With no arguments, score both fixed synthetic experiments generated by
# scripts/run.sh and write scoring/scores_test.json. When
# scoring/scores_train.json exists, the test pass scores the same method names.

set -e

WORKSPACE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$WORKSPACE_DIR"
export PYTHONPATH="$WORKSPACE_DIR:${PYTHONPATH:-}"

mkdir -p scoring

if [[ "$#" -gt 0 ]]; then
  DATA_PATH="${1:-data/riemanline_synthetic.json}"
  OUTPUT_DIR="${2:-outputs}"
  SCORES_PATH="${3:-scoring/scores_test.json}"
  python -m eval.test.evaluate \
    --pair "$DATA_PATH" "$OUTPUT_DIR" \
    --scores "$SCORES_PATH" \
    --train-scores scoring/scores_train.json
else
  python -m eval.test.evaluate \
    --pair data/riemanline_synthetic.json outputs \
    --pair data/riemanline_synthetic_harder.json outputs/harder \
    --scores scoring/scores_test.json \
    --train-scores scoring/scores_train.json
fi
